o=c.id_quirofano ORDER BY c.fecha_programada DESC",'title'=>'Cirugías'],'internaciones'=>['sql'=>"SELECT i.fecha_ingreso,i.fecha_alta,p.nombre paciente,h.numero habitacion,i.estado FROM internaciones i JOIN personas p ON p.id_persona=i.id_persona JOIN habitaciones h ON h.id_habitacion=i.id_habitacion ORDER BY i.fecha_ingreso DESC",'title'=>'Internaciones'],'historias'=>['sql'=>"SELECT h.fecha_apertura,p.ci,p.nombre,h.antecedentes,h.alergias,h.observaciones FROM historias_clinicas h JOIN personas p ON p.id_persona=h.id_persona ORDER BY h.fecha_apertura DESC",'title'=>'Historias clínicas'],'personal'=>['sql'=>"SELECT p.ci,p.nombre,m.matricula_profesional,m.tipo_contrato,m.activo FROM medicos m JOIN personas p ON p.id_persona=m.id_persona ORDER BY p.nombre",'title'=>'Personal médico'],'facturacion'=>['sql'=>"SELECT f.fecha_emision,p.nombre paciente,f.subtotal,f.monto_cobertura_seguro,f.total,f.estado FROM facturas f JOIN paciente_seguro ps ON ps.id_paciente_seguro=f.id_paciente_seguro JOIN personas p ON p.id_persona=ps.id_persona ORDER BY f.fecha_emision DESC",'title'=>'Facturación']]; if(!isset($exports[$ep]))$ep='pacientes'; $rows=$pdo->query($exports[$ep]['sql'])->fetchAll(PDO::FETCH_ASSOC); header('Content-Type: application/vnd.ms-excel; charset=UTF-8'); header('Content-Disposition: attachment; filename=salud_vida_'.$ep.'.xls'); header('Cache-Control: max-age=0'); echo '<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:Arial}h2{color:#087f8c}table{border-collapse:collapse;font-family:Arial;min-width:900px}th{background:#087f8c;color:#fff;font-weight:bold;padding:10px;border:1px solid #075e68}td{padding:8px;border:1px solid #d0d0d0}tr:nth-child(even){background:#eefaf8}</style></head><body><h2>Salud Vida — '.e($exports[$ep]['title']).'</h2><table><tr>'; if($rows){foreach(array_keys($rows[0]) as $h)echo '<th>'.e((string)$h).'</th>'; echo '</tr>';foreach($rows as $r){echo '<tr>';foreach($r as $v)echo '<td>'.e((string)$v).'</td>';echo '</tr>';}} 