        if ($action === 'crear_consulta' && can(['ADMINISTRADOR','MEDICO','ENFERMERO'])) {
            $hist=one($pdo,'SELECT id_historia FROM historias_clinicas WHERE id_persona=? ORDER BY fecha_apertura DESC LIMIT 1',[(int)post('id_persona')]);
            if(!$hist){ $pdo->prepare('INSERT INTO historias_clinicas(id_persona) VALUES(?)')->execute([(int)post('id_persona')]); $hist=['id_historia'=>$pdo->lastInsertId()]; }
            $pdo->prepare('INSERT INTO consultas(consulta_padre,id_persona,id_medico,id_especialidad,id_historia,id_consultorio,fecha_hora,duracion_estimada_minutos,motivo,tipo_consulta) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([post('consulta_padre')?:null,(int)post('id_persona'),(int)post('id_medico'),(int)post('id_especialidad'),$hist['id_historia'],(int)post('id_consultorio'),str_replace('T',' ',(string)post('fecha_hora')),max(5,(int)post('duracion',30)),post('motivo')?:null,post('tipo_consulta','PRIMERA_VEZ')]); flash('ok','Consulta programada correctamente.'); go('index.php?page=consultas');
        }
        if ($action === 'estado_consulta' && can(['ADMINISTRADOR','MEDICO','ENFERMERO'])) { $pdo->prepare('UPDATE consultas SET estado=? WHERE id_consulta=?')->execute([post('estado'),(int)post('id_consulta')]); flash('ok','Estado de consulta actualizado.'); go('index.php?page=consultas'); }

        if ($action === 'crear_cirugia' && can(['ADMINISTRADOR','MEDICO'])) {
            $pdo->prepare('INSERT INTO cirugias(id_persona,id_quirofano,id_especialidad,id_cirujano_principal,fecha_programada,duracion_estimada_minutos,diagnostico_prequirurgico,estado) VALUES(?,?,?,?,?,?,?,?)')->execute([(int)post('id_persona'),(int)post('id_quirofano'),(int)post('id_especialidad'),(int)post('id_cirujano'),str_replace('T',' ',(string)post('fecha_programada')),max(10,(int)post('duracion',120)),post('diagnostico')?:null,post('estado','PROGRAMADA')]); flash('ok','Cirugía registrada correctamente.'); go('index.php?page=cirugias');
        }
        if ($action === 'estado_cirugia' && can(['ADMINISTRADOR','MEDICO'])) { $pdo->prepare('UPDATE cirugias SET estado=? WHERE id_cirugia=?')->execute([post('estado'),(int)post('id_cirugia')]); flash('ok','Estado de cirugía actualizado.'); go('index.php?page=cirugias'); }

        if ($action === 'crear_internacion' && can(['ADMINISTRADOR','MEDICO','ENFERMERO'])) {
            $pdo->beginTransaction();
            $pdo->prepare('INSERT INTO ordenes_internacion(id_consulta,motivo) VALUES(?,?)')->execute([(int)post('id_consulta'),trim((string)post('motivo'))]); $orden=(int)$pdo->lastInsertId();
            $pdo->prepare('INSERT INTO internaciones(id_orden,id_persona,id_habitacion,fecha_ingreso,estado) VALUES(?,?,?,?,\'ACTIVA\')')->execute([$orden,(int)post('id_persona'),(int)post('id_habitacion'),str_replace('T',' ',(string)post('fecha_ingreso'))]);
            $pdo->prepare("UPDATE habitaciones SET estado='OCUPADA' WHERE id_habitacion=?")->execute([(int)post('id_habitacion')]); $pdo->commit(); flash('ok','Internación creada y habitación marcada como ocupada.'); go('index.php?page=internaciones');
        }
        if ($action === 'alta_internacion' && can(['ADMINISTRADOR','MEDICO'])) {
            $pdo->beginTransaction(); $id=(int)post('id_internacion'); $pdo->prepare("UPDATE internaciones SET estado='FINALIZADA',fecha_alta=NOW(),id_medico_autoriza_alta=? WHERE id_internacion=?")->execute([$_SESSION['user']['id_persona'],$id]); $h=one($pdo,'SELECT id_habitacion FROM internaciones WHERE id_internacion=?',[$id]); if($h) $pdo->prepare("UPDATE habitaciones SET estado='DISPONIBLE' WHERE id_habitacion=?")->execute([$h['id_habitacion']]); $pdo->commit(); flash('ok','Alta registrada y habitación liberada.'); go('index.php?page=internaciones'); }

        if ($action === 'crear_factura' && can(['ADMINISTRADOR','FACTURADOR'])) {
            $pdo->beginTransaction();
            $df=$pdo->prepare('INSERT INTO datos_facturacion(nit_ci,razon_social,tipo_documento_fiscal) VALUES(?,?,?)'); $df->execute([trim((string)post('nit_ci')),trim((string)post('razon_social')),post('tipo_documento_fiscal')]); $dfid=(int)$pdo->lastInsertId();
            $sub=(float)post('precio_unitario')*(int)post('cantidad',1); $cob=min($sub,max(0,(float)post('cobertura',0)));
            $pdo->prepare('INSERT INTO facturas(id_paciente_seguro,id_usuario_factura,id_datos_facturacion,tipo_pago,subtotal,monto_cobertura_seguro,estado) VALUES(?,?,?,?,?,?,?)')->execute([(int)post('id_paciente_seguro'),$_SESSION['user']['id_usuario'],$dfid,post('tipo_pago'),$sub,$cob,post('estado','PENDIENTE')]); $fid=(int)$pdo->lastInsertId();
            $src=['consulta'=>null,'cirugia'=>null,'internacion'=>null]; $src[(string)post('origen')]=(int)post('id_origen'); $pdo->prepare('INSERT INTO factura_detalle(id_factura,id_servicio,id_consulta,id_cirugia,id_internacion,cantidad,precio_unitario) VALUES(?,?,?,?,?,?,?)')->execute([$fid,(int)post('id_servicio'),$src['consulta'],$src['cirugia'],$src['internacion'],max(1,(int)post('cantidad',1)),max(0,(float)post('precio_unitario'))]); $pdo->commit(); flash('ok','Factura emitida correctamente.'); go('index.php?page=facturacion');
        }
        if ($action === 'estado_factura' && can(['ADMINISTRADOR','FACTURADOR'])) { $pdo->prepare('UPDATE facturas SET estado=? WHERE id_factura=?')->execute([post('estado'),(int)post('id_factura')]); flash('ok','Estado de factura actualizado.'); go('index.php?page=facturacion'); }
    } catch (Throwable $e) { if($pdo->inTransaction()) $pdo->rollBack(); $target=$_GET['page']??'dashboard'; $msg=$e->getMessage(); if($e instanceof PDOException && (string)$e->getCode()==='23000'){ if(str_contains($msg,'usuarios')||str_contains($msg,'nombre_usuario'))$msg='Usuario ya registrado.'; elseif(str_contains($msg,'personas')||str_contains($msg,'ci'))$msg='Persona ya registrada.'; elseif(str_contains($msg,'servicios_medicos'))$msg='Servicio médico ya registrado.'; elseif(str_contains($msg,'especialidades'))$msg='Especialidad ya registrada.'; else $msg='El registro ya existe o duplica información.'; } elseif(str_contains($msg,'ya está registrado')||str_contains($msg,'Ya existe')){} else $msg='No se pudo completar la operación. Verifica los datos y las restricciones de la base de datos.'; fail_back($target,$msg); }
}
